#!/usr/bin/python3
import json,sqlite3,subprocess,datetime
from pathlib import Path
def rows(db,query,args=()):return [dict(r) for r in db.execute(query,args)]
def ctl(*args):return subprocess.check_output(['systemctl',*args],text=True).strip()
db=sqlite3.connect('file:/var/lib/news-flow/news-flow-runtime/write.sqlite?mode=ro',uri=True,timeout=10);db.row_factory=sqlite3.Row
settings={k:v for k,v in (line.split('=',1) for line in ctl('show','news-flow.service','-p','ActiveState','-p','SubState','-p','MainPID','-p','NRestarts','-p','MemoryCurrent','-p','CPUUsageNSec','-p','ExecMainStatus').splitlines())}
writer={k:v for k,v in (line.split('=',1) for line in ctl('show','news-flow-writer.service','-p','ActiveState','-p','SubState','-p','MainPID','-p','NRestarts','-p','MemoryCurrent','-p','CPUUsageNSec','-p','ExecMainStatus','-p','ControlGroup').splitlines())}
shared={k:v for k,v in (line.split('=',1) for line in ctl('show','news-flow.slice','-p','ActiveState','-p','MemoryCurrent','-p','CPUUsageNSec','-p','MemoryMax','-p','CPUQuotaPerSecUSec').splitlines())}
checks=json.loads(Path('/var/lib/news-flow/deployment-check.json').read_text());canaryPath=Path('/var/lib/news-flow/writer-split-live-check.json');canary=json.loads((canaryPath if canaryPath.exists() else Path('/var/lib/news-flow/canary-verification.json')).read_text())
report={'checkedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'release':str(Path('/opt/news-flow/current').resolve()),'node':checks['nodeVersion'],'service':settings,'enabled':ctl('is-enabled','news-flow.service'),'egressService':ctl('is-active','news-flow-egress.service'),'preflight':checks,'canary':canary,'runtime':{'cycles':rows(db,'SELECT id,started,finished FROM cycles ORDER BY started DESC LIMIT 3'),'configuredPublishersInQueue':rows(db,'SELECT count(DISTINCT site) AS count FROM tasks')[0]['count'],'publishersProcessed':rows(db,"SELECT count(DISTINCT site) AS count FROM tasks WHERE state IN ('done','held')")[0]['count'],'tasks':rows(db,'SELECT state,count(*) AS count FROM tasks GROUP BY state'),'requests':rows(db,'SELECT state,count(*) AS count FROM requests GROUP BY state'),'outbox':rows(db,'SELECT state,count(*) AS count FROM outbox GROUP BY state'),'heldReasons':rows(db,"SELECT reason,count(*) AS count FROM tasks WHERE state='held' GROUP BY reason ORDER BY count(*) DESC LIMIT 15"),'pendingOutboxReasons':rows(db,"SELECT reason,count(*) AS count FROM outbox WHERE state IN ('pending','held','sending') GROUP BY reason ORDER BY count(*) DESC LIMIT 10")}}
report['writerService']=writer;report['sharedBudget']=shared;report['writerEnabled']=ctl('is-enabled','news-flow-writer.service');report['independentProcesses']=settings['MainPID']!='0' and writer['MainPID']!='0' and settings['MainPID']!=writer['MainPID'];report['writerLease']=rows(db,"SELECT id,expires FROM runner WHERE id='es5_writer'")
db.close();report['healthy']=settings['ActiveState']=='active' and settings['SubState']=='running' and settings['NRestarts']=='0' and writer['ActiveState']=='active' and writer['SubState']=='running' and writer['NRestarts']=='0' and report['independentProcesses'] and shared['ActiveState']=='active' and checks['verified'] and checks['tests']['pass']>=163 and canary['verified']
Path('/var/lib/news-flow/deployment-status.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
